<?php
require_once __DIR__.'/auth.php';$msg='';$err='';
function upload_designer_photo(?string $old=null):?string{if(empty($_FILES['photo']['name']))return $old;$f=$_FILES['photo'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>5*1024*1024)throw new RuntimeException('Foto maksimal 5 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$map=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($map[$mime]))throw new RuntimeException('Foto harus JPG, PNG, atau WEBP.');$name='designer_'.bin2hex(random_bytes(6)).'.'.$map[$mime];$dir=__DIR__.'/../assets/team/';if(!is_dir($dir))mkdir($dir,0755,true);if(!move_uploaded_file($f['tmp_name'],$dir.$name))throw new RuntimeException('Foto tidak dapat disimpan.');if($old&&str_starts_with($old,'assets/team/')&&is_file(__DIR__.'/../'.$old))@unlink(__DIR__.'/../'.$old);return 'assets/team/'.$name;}
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf($_POST['csrf_token']??'');$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='save'){$name=trim($_POST['name']??'');$spec=trim($_POST['specialty']??'');$active=isset($_POST['active'])?1:0;if(!$name)throw new RuntimeException('Nama wajib diisi.');$old=null;if($id){$q=$pdo->prepare('SELECT photo FROM designers WHERE id=?');$q->execute([$id]);$old=$q->fetchColumn()?:null;}$photo=upload_designer_photo($old)??'assets/admin.png';if($id)$pdo->prepare('UPDATE designers SET name=?,specialty=?,photo=?,active=? WHERE id=?')->execute([$name,$spec,$photo,$active,$id]);else $pdo->prepare('INSERT INTO designers(name,specialty,photo,active) VALUES(?,?,?,?)')->execute([$name,$spec,$photo,$active]);$msg='Data designer tersimpan.';}elseif($action==='delete'){$q=$pdo->prepare('SELECT photo FROM designers WHERE id=?');$q->execute([$id]);$p=$q->fetchColumn();$pdo->prepare('DELETE FROM designers WHERE id=?')->execute([$id]);if($p&&str_starts_with($p,'assets/team/')&&is_file(__DIR__.'/../'.$p))@unlink(__DIR__.'/../'.$p);$msg='Designer dihapus.';}}catch(Throwable $x){$err=$x->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM designers WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}$rows=$pdo->query('SELECT * FROM designers ORDER BY name')->fetchAll();admin_header('Kelola Designer','designers');if($msg)echo '<div class="notice success-notice">'.e($msg).'</div>';if($err)echo '<div class="notice error-notice">'.e($err).'</div>';
?><section class="panel"><h2><?=$edit?'Edit Designer':'Tambah Designer'?></h2><form method="post" enctype="multipart/form-data" class="member-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'0')?>"><label>Nama<input name="name" value="<?=e($edit['name']??'')?>" required></label><label>Keahlian<input name="specialty" value="<?=e($edit['specialty']??'Graphic Designer')?>"></label><label>Foto<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"><small>JPG/PNG/WEBP, maksimal 5 MB.</small></label><label class="check"><input type="checkbox" name="active" value="1" <?=(!isset($edit['active'])||$edit['active'])?'checked':''?>> Aktif</label><div class="full"><button class="save">Simpan Designer</button></div></form></section><section class="panel" style="margin-top:22px"><h2>Daftar Designer</h2><div class="member-admin-grid"><?php foreach($rows as $r):?><article class="member-admin-card"><img src="../<?=e($r['photo'])?>" alt="<?=e($r['name'])?>"><div><h3><?=e($r['name'])?></h3><b><?=e($r['specialty'])?></b><p><?= $r['active']?'Aktif':'Nonaktif' ?></p><div class="member-card-actions"><a class="save" href="designers.php?edit=<?=$r['id']?>">Edit</a><form method="post" onsubmit="return confirm('Hapus designer ini?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="del">Hapus</button></form></div></div></article><?php endforeach;?></div></section><?php admin_footer(); ?>
